/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     public var val: Int
 *     public var left: TreeNode?
 *     public var right: TreeNode?
 *     public init() { self.val = 0; self.left = nil; self.right = nil; }
 *     public init(_ val: Int) { self.val = val; self.left = nil; self.right = nil; }
 *     public init(_ val: Int, _ left: TreeNode?, _ right: TreeNode?) {
 *         self.val = val
 *         self.left = left
 *         self.right = right
 *     }
 * }
 */
class Solution {
    func buildTree(_ preorder: [Int], _ inorder: [Int]) -> TreeNode? {
        if preorder.isEmpty || inorder.isEmpty {
            return nil
        }

        let rootValue = preorder[0]
        let root = TreeNode(rootValue)
        guard let mid = inorder.firstIndex(of: rootValue) else {
            return root
        }

        root.left = buildTree(
            Array(preorder[1..<(mid + 1)]),
            Array(inorder[0..<mid])
        )

        root.right = buildTree(
            Array(preorder[(mid + 1)..<preorder.count]),
            Array(inorder[(mid + 1)..<inorder.count])
        )

        return root
    }
}

impl Solution {
    pub fn build_tree(preorder: Vec<i32>, inorder: Vec<i32>) -> Option<Rc<RefCell<TreeNode>>> {
        if preorder.is_empty() || inorder.is_empty() {
            return None;
        }

        let root_val = preorder[0];
        let mid = inorder.iter().position(|&x| x == root_val).unwrap();

        let mut root = TreeNode::new(root_val);
        root.left = Self::build_tree(
            preorder[1..=mid].to_vec(),
            inorder[..mid].to_vec(),
        );
        root.right = Self::build_tree(
            preorder[mid + 1..].to_vec(),
            inorder[mid + 1..].to_vec(),
        );

        Some(Rc::new(RefCell::new(root)))
    }
}

