 * public class TreeNode {
 *     public var val: Int
 *     public var left: TreeNode?
 *     public var right: TreeNode?
 *     public init() { self.val = 0; self.left = nil; self.right = nil; }
 *     public init(_ val: Int) { self.val = val; self.left = nil; self.right = nil; }
 *     public init(_ val: Int, _ left: TreeNode?, _ right: TreeNode?) {
 *         self.val = val
 *         self.left = left
 *         self.right = right
 *     }
 * }
 */
class Solution {
    var preIndex = 0
    var indexMap = [Int: Int]()

    func buildTree(_ preorder: [Int], _ inorder: [Int]) -> TreeNode? {
        for (index, value) in inorder.enumerated() {
            indexMap[value] = index
        }
        return dfs(preorder, 0, inorder.count - 1)
    }

    private func dfs(_ preorder: [Int], _ left: Int, _ right: Int) -> TreeNode? {
        if left > right {
            return nil
        }

        let rootVal = preorder[preIndex]
        preIndex += 1
        let root = TreeNode(rootVal)
        let mid = indexMap[rootVal]!

        root.left = dfs(preorder, left, mid - 1)
        root.right = dfs(preorder, mid + 1, right)

        return root
    }
}

impl Solution {
    pub fn build_tree(preorder: Vec<i32>, inorder: Vec<i32>) -> Option<Rc<RefCell<TreeNode>>> {
        let mut indices = HashMap::new();
        for (i, &val) in inorder.iter().enumerate() {
            indices.insert(val, i as i32);
        }
        let mut pre_idx = 0;
        Self::dfs(&preorder, &indices, &mut pre_idx, 0, inorder.len() as i32 - 1)
    }

    fn dfs(
        preorder: &[i32],
        indices: &HashMap<i32, i32>,
        pre_idx: &mut usize,
        l: i32,
        r: i32,
    ) -> Option<Rc<RefCell<TreeNode>>> {
        if l > r {
            return None;
        }
        let root_val = preorder[*pre_idx];
        *pre_idx += 1;
        let mid = *indices.get(&root_val).unwrap();
        let mut root = TreeNode::new(root_val);
        root.left = Self::dfs(preorder, indices, pre_idx, l, mid - 1);
        root.right = Self::dfs(preorder, indices, pre_idx, mid + 1, r);
        Some(Rc::new(RefCell::new(root)))
    }
}

